import { z } from 'zod';

// A measured result is the point of a case study, so the model requires one.
// A field that is optional in the schema is a field that will be left blank.
const outcome = z.object({
  metric: z.string().min(1).max(80),      // 'Checkout completion'
  before: z.string().min(1).max(40),      // '61%'
  after: z.string().min(1).max(40),       // '78%'
  measuredOver: z.string().min(1).max(80),// 'eight weeks after launch'
});

export const caseStudy = z.object({
  slug: z.string().regex(/^[a-z0-9][a-z0-9-]{0,63}$/),
  client: z.string().min(1).max(80),
  // 160 because that is what the search result and the card both allow.
  // The limit belongs next to the field, not in a style guide nobody reads.
  summary: z.string().trim().max(160),
  constraint: z.string().trim().max(600),
  approach: z.string().trim().max(2000),
  outcomes: z.array(outcome).min(1).max(4),
  // A relationship, not a typed-in name: deleting an author is then a
  // decision the system makes rather than a byline pointing at nothing.
  authorId: z.string().uuid(),
  publishedAt: z.string().datetime().nullable(),
});

export type CaseStudy = z.infer<typeof caseStudy>;
